from __future__ import annotations

import random
import time
from collections.abc import Callable, Iterable, Iterator, Mapping
from typing import Any

import httpx

from .exceptions import (
    ConflictError,
    LumenAPIError,
    NotFoundError,
    RateLimitError,
    StaleCursorError,
)
from .models import (
    Annotation,
    BatchCreateResult,
    Error,
    Project,
    ReviewResult,
    ReviewVerdict,
    TaskCreate,
)

DEFAULT_BASE_URL = "https://api.lumen.internal/v1"
MAX_BATCH_SIZE = 100


class LumenClient:
    """Synchronous client for the Lumen Annotation API."""

    def __init__(
        self,
        api_key: str,
        *,
        base_url: str = DEFAULT_BASE_URL,
        timeout: float | httpx.Timeout = 30.0,
        transport: httpx.BaseTransport | None = None,
        sleeper: Callable[[float], None] = time.sleep,
        jitter: Callable[[float], float] | None = None,
        max_attempts: int = 5,
    ) -> None:
        self._sleeper = sleeper
        self._jitter = jitter or (lambda delay: random.uniform(0, delay * 0.1))
        self._max_attempts = max_attempts
        self._http = httpx.Client(
            base_url=base_url,
            headers={"X-Lumen-Key": api_key, "Accept": "application/json"},
            timeout=timeout,
            transport=transport,
        )
        self.projects = ProjectsResource(self)
        self.tasks = TasksResource(self)
        self.annotations = AnnotationsResource(self)

    def close(self) -> None:
        self._http.close()

    def __enter__(self) -> "LumenClient":
        return self

    def __exit__(self, *exc_info: object) -> None:
        self.close()

    def _request(
        self,
        method: str,
        path: str,
        *,
        params: Mapping[str, Any] | None = None,
        json: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        last_response: httpx.Response | None = None

        for attempt in range(1, self._max_attempts + 1):
            response = self._http.request(method, path, params=params, json=json)
            last_response = response

            if response.status_code < 400 or response.status_code == 207:
                return self._json_object(response)

            error = self._parse_error(response)
            if not self._should_retry(response, error):
                self._raise_for_response(response, error)

            if attempt == self._max_attempts:
                self._raise_for_response(response, error)

            self._sleeper(self._retry_delay(response, attempt))

        if last_response is None:
            raise LumenAPIError("request was not attempted")
        self._raise_for_response(last_response, self._parse_error(last_response))

    def _should_retry(self, response: httpx.Response, error: Error | None) -> bool:
        if response.status_code == 429:
            return True
        if 500 <= response.status_code <= 599:
            return error.retryable if error is not None else True
        return False

    def _retry_delay(self, response: httpx.Response, attempt: int) -> float:
        retry_after = response.headers.get("Retry-After")
        if retry_after is not None:
            try:
                return max(0.0, float(retry_after))
            except ValueError:
                pass

        base_delay = 0.5 * (2 ** (attempt - 1))
        return base_delay + max(0.0, self._jitter(base_delay))

    def _json_object(self, response: httpx.Response) -> dict[str, Any]:
        try:
            data = response.json()
        except ValueError as exc:
            raise LumenAPIError("response body was not valid JSON", status_code=response.status_code) from exc
        if not isinstance(data, dict):
            raise LumenAPIError("response body was not a JSON object", status_code=response.status_code)
        return data

    def _parse_error(self, response: httpx.Response) -> Error | None:
        try:
            data = response.json()
        except ValueError:
            return None
        if not isinstance(data, Mapping):
            return None
        error_data = data.get("error")
        if not isinstance(error_data, Mapping):
            return None
        return Error.from_dict(error_data)

    def _raise_for_response(self, response: httpx.Response, error: Error | None) -> None:
        message = error.message if error is not None and error.message else response.reason_phrase
        kwargs = {"error": error, "status_code": response.status_code}
        if response.status_code == 404:
            raise NotFoundError(message, **kwargs)
        if response.status_code == 409:
            raise ConflictError(message, **kwargs)
        if response.status_code == 410:
            raise StaleCursorError(message, **kwargs)
        if response.status_code == 429:
            raise RateLimitError(message, **kwargs)
        raise LumenAPIError(message, **kwargs)


class ProjectsResource:
    def __init__(self, client: LumenClient) -> None:
        self._client = client

    def list(self, *, limit: int = 50, cursor: str | None = None) -> Iterator[Project]:
        if not 1 <= limit <= 200:
            raise ValueError("limit must be between 1 and 200")

        next_cursor = cursor
        while True:
            params: dict[str, Any] = {"limit": limit}
            if next_cursor is not None:
                params["cursor"] = next_cursor
            data = self._client._request("GET", "/projects", params=params)
            for item in data.get("items", []):
                if isinstance(item, Mapping):
                    yield Project.from_dict(item)
            next_cursor = data.get("next_cursor")
            if next_cursor is None:
                break

    def get(self, project_id: str) -> Project:
        data = self._client._request("GET", f"/projects/{project_id}")
        return Project.from_dict(data)


class TasksResource:
    def __init__(self, client: LumenClient) -> None:
        self._client = client

    def batch_create(
        self,
        project_id: str,
        tasks: Iterable[TaskCreate | Mapping[str, Any]],
    ) -> list[BatchCreateResult]:
        normalized = [
            task if isinstance(task, TaskCreate) else TaskCreate.from_dict(task)
            for task in tasks
        ]
        results: list[BatchCreateResult] = []

        for offset in range(0, len(normalized), MAX_BATCH_SIZE):
            chunk = normalized[offset : offset + MAX_BATCH_SIZE]
            data = self._client._request(
                "POST",
                f"/projects/{project_id}/tasks:batchCreate",
                json={"tasks": [task.to_dict() for task in chunk]},
            )
            for item in data.get("results", []):
                if isinstance(item, Mapping):
                    results.append(BatchCreateResult.from_dict(item, index_offset=offset))

        return results


class AnnotationsResource:
    def __init__(self, client: LumenClient) -> None:
        self._client = client

    def list_for_task(
        self,
        task_id: str,
        *,
        limit: int = 50,
        cursor: str | None = None,
    ) -> Iterator[Annotation]:
        if not 1 <= limit <= 200:
            raise ValueError("limit must be between 1 and 200")

        next_cursor = cursor
        while True:
            params: dict[str, Any] = {"limit": limit}
            if next_cursor is not None:
                params["cursor"] = next_cursor
            data = self._client._request("GET", f"/tasks/{task_id}/annotations", params=params)
            for item in data.get("items", []):
                if isinstance(item, Mapping):
                    yield Annotation.from_dict(item)
            next_cursor = data.get("next_cursor")
            if next_cursor is None:
                break

    def review(
        self,
        annotation_id: str,
        *,
        verdict: ReviewVerdict,
        note: str | None = None,
    ) -> ReviewResult:
        data = self._client._request(
            "POST",
            f"/annotations/{annotation_id}:review",
            json={"verdict": verdict, "note": note},
        )
        return ReviewResult.from_dict(data, annotation_id=annotation_id)

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Literal, Mapping

ProjectStatus = Literal["active", "archived"]
TaskState = Literal["queued", "in_progress", "done"]
BatchStatus = Literal["created", "error"]
ReviewVerdict = Literal["approve", "reject"]


def _dict(value: Mapping[str, Any] | dict[str, Any], field_name: str) -> dict[str, Any]:
    if not isinstance(value, Mapping):
        raise TypeError(f"{field_name} must be a mapping")
    return dict(value)


@dataclass(frozen=True, slots=True)
class Error:
    code: str
    message: str
    retryable: bool = False

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> "Error":
        return cls(
            code=str(data.get("code", "")),
            message=str(data.get("message", "")),
            retryable=bool(data.get("retryable", False)),
        )

    def to_dict(self) -> dict[str, Any]:
        return {
            "code": self.code,
            "message": self.message,
            "retryable": self.retryable,
        }


@dataclass(frozen=True, slots=True)
class Project:
    id: str
    name: str
    created_at: str
    status: ProjectStatus
    label_schema: dict[str, Any]

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> "Project":
        return cls(
            id=str(data["id"]),
            name=str(data["name"]),
            created_at=str(data["created_at"]),
            status=data["status"],
            label_schema=_dict(data["label_schema"], "label_schema"),
        )


@dataclass(frozen=True, slots=True)
class TaskCreate:
    external_id: str
    payload: dict[str, Any]
    priority: int = 3

    def __post_init__(self) -> None:
        if not 1 <= self.priority <= 5:
            raise ValueError("priority must be between 1 and 5")

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> "TaskCreate":
        return cls(
            external_id=str(data["external_id"]),
            payload=_dict(data["payload"], "payload"),
            priority=int(data.get("priority", 3)),
        )

    def to_dict(self) -> dict[str, Any]:
        return {
            "external_id": self.external_id,
            "payload": self.payload,
            "priority": self.priority,
        }


@dataclass(frozen=True, slots=True)
class Task(TaskCreate):
    id: str = ""
    state: TaskState = "queued"

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> "Task":
        return cls(
            external_id=str(data["external_id"]),
            payload=_dict(data["payload"], "payload"),
            priority=int(data.get("priority", 3)),
            id=str(data["id"]),
            state=data["state"],
        )

    def to_dict(self) -> dict[str, Any]:
        body = super().to_dict()
        body.update({"id": self.id, "state": self.state})
        return body


@dataclass(frozen=True, slots=True)
class Annotation:
    id: str
    task_id: str
    labels: dict[str, Any]
    annotator: str
    confidence: float

    def __post_init__(self) -> None:
        if not 0 <= self.confidence <= 1:
            raise ValueError("confidence must be between 0 and 1")

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> "Annotation":
        return cls(
            id=str(data["id"]),
            task_id=str(data["task_id"]),
            labels=_dict(data["labels"], "labels"),
            annotator=str(data["annotator"]),
            confidence=float(data["confidence"]),
        )


@dataclass(frozen=True, slots=True)
class BatchCreateResult:
    index: int
    status: BatchStatus
    task: Task | None = None
    error: Error | None = None

    @classmethod
    def from_dict(cls, data: Mapping[str, Any], *, index_offset: int = 0) -> "BatchCreateResult":
        task_data = data.get("task")
        error_data = data.get("error")
        return cls(
            index=int(data["index"]) + index_offset,
            status=data["status"],
            task=Task.from_dict(task_data) if isinstance(task_data, Mapping) else None,
            error=Error.from_dict(error_data) if isinstance(error_data, Mapping) else None,
        )


@dataclass(frozen=True, slots=True)
class ReviewResult:
    annotation_id: str
    verdict: ReviewVerdict
    note: str | None = None
    already_applied: bool = False
    raw: dict[str, Any] = field(default_factory=dict)

    @classmethod
    def from_dict(cls, data: Mapping[str, Any], *, annotation_id: str) -> "ReviewResult":
        return cls(
            annotation_id=str(data.get("annotation_id", annotation_id)),
            verdict=data["verdict"],
            note=data.get("note"),
            already_applied=bool(data.get("already_applied", False)),
            raw=dict(data),
        )

from __future__ import annotations

import json
from collections.abc import Callable
from typing import Any

import httpx
import pytest

from lumen import (
    ConflictError,
    LumenClient,
    RateLimitError,
    StaleCursorError,
    TaskCreate,
)


def response(status_code: int, data: dict[str, Any], headers: dict[str, str] | None = None) -> httpx.Response:
    return httpx.Response(status_code, json=data, headers=headers)


def client_for(
    handler: Callable[[httpx.Request], httpx.Response],
    *,
    sleeps: list[float] | None = None,
) -> LumenClient:
    return LumenClient(
        "test-key",
        transport=httpx.MockTransport(handler),
        sleeper=(sleeps.append if sleeps is not None else (lambda delay: None)),
        jitter=lambda delay: 0.0,
    )


def api_path(request: httpx.Request) -> str:
    assert request.headers["X-Lumen-Key"] == "test-key"
    return request.url.path.removeprefix("/v1")


def project(project_id: str) -> dict[str, Any]:
    return {
        "id": project_id,
        "name": f"Project {project_id}",
        "created_at": "2026-01-01T00:00:00Z",
        "status": "active",
        "label_schema": {"type": "classification"},
    }


def task(task_id: str, external_id: str = "external-1") -> dict[str, Any]:
    return {
        "id": task_id,
        "external_id": external_id,
        "payload": {"text": "hello"},
        "priority": 3,
        "state": "queued",
    }


def test_projects_list_paginates_across_three_pages() -> None:
    seen: list[str | None] = []
    pages = {
        None: {"items": [project("p1")], "next_cursor": "c2"},
        "c2": {"items": [project("p2")], "next_cursor": "c3"},
        "c3": {"items": [project("p3")], "next_cursor": None},
    }

    def handler(request: httpx.Request) -> httpx.Response:
        assert request.method == "GET"
        assert api_path(request) == "/projects"
        assert request.url.params["limit"] == "2"
        cursor = request.url.params.get("cursor")
        seen.append(cursor)
        return response(200, pages[cursor])

    with client_for(handler) as client:
        items = list(client.projects.list(limit=2))

    assert [item.id for item in items] == ["p1", "p2", "p3"]
    assert seen == [None, "c2", "c3"]


def test_stale_cursor_raises_typed_error() -> None:
    def handler(request: httpx.Request) -> httpx.Response:
        assert api_path(request) == "/projects"
        return response(
            410,
            {"error": {"code": "stale_cursor", "message": "cursor expired", "retryable": False}},
        )

    with client_for(handler) as client:
        with pytest.raises(StaleCursorError) as exc_info:
            list(client.projects.list(cursor="expired"))

    assert exc_info.value.error is not None
    assert exc_info.value.error.code == "stale_cursor"
    assert exc_info.value.status_code == 410


def test_429_retries_and_honors_retry_after_sleep() -> None:
    sleeps: list[float] = []
    calls = 0

    def handler(request: httpx.Request) -> httpx.Response:
        nonlocal calls
        calls += 1
        if calls == 1:
            return response(
                429,
                {"error": {"code": "rate_limited", "message": "slow down", "retryable": True}},
                headers={"Retry-After": "2.5"},
            )
        return response(200, {"items": [project("p1")], "next_cursor": None})

    with client_for(handler, sleeps=sleeps) as client:
        items = list(client.projects.list())

    assert [item.id for item in items] == ["p1"]
    assert sleeps == [2.5]
    assert calls == 2


def test_429_raises_rate_limit_after_max_attempts() -> None:
    sleeps: list[float] = []

    def handler(request: httpx.Request) -> httpx.Response:
        return response(
            429,
            {"error": {"code": "rate_limited", "message": "slow down", "retryable": True}},
            headers={"Retry-After": "1"},
        )

    with client_for(handler, sleeps=sleeps) as client:
        with pytest.raises(RateLimitError):
            list(client.projects.list())

    assert sleeps == [1.0, 1.0, 1.0, 1.0]


@pytest.mark.parametrize(
    ("count", "expected_chunk_sizes"),
    [
        (100, [100]),
        (101, [100, 1]),
        (250, [100, 100, 50]),
    ],
)
def test_batch_create_chunks_at_100_items(count: int, expected_chunk_sizes: list[int]) -> None:
    chunk_sizes: list[int] = []

    def handler(request: httpx.Request) -> httpx.Response:
        assert request.method == "POST"
        assert api_path(request) == "/projects/p1/tasks:batchCreate"
        payload = json.loads(request.content)
        chunk_sizes.append(len(payload["tasks"]))
        results = [
            {
                "index": index,
                "status": "created",
                "task": task(f"t{sum(chunk_sizes[:-1]) + index}", item["external_id"]),
                "error": None,
            }
            for index, item in enumerate(payload["tasks"])
        ]
        return response(207, {"results": results})

    tasks = [TaskCreate(external_id=f"e{i}", payload={"i": i}) for i in range(count)]

    with client_for(handler) as client:
        results = client.tasks.batch_create("p1", tasks)

    assert chunk_sizes == expected_chunk_sizes
    assert len(results) == count
    assert [result.index for result in results] == list(range(count))


def test_batch_create_aggregates_207_partial_failure() -> None:
    def handler(request: httpx.Request) -> httpx.Response:
        payload = json.loads(request.content)
        assert len(payload["tasks"]) == 3
        return response(
            207,
            {
                "results": [
                    {"index": 0, "status": "created", "task": task("t1", "e1"), "error": None},
                    {
                        "index": 1,
                        "status": "error",
                        "task": None,
                        "error": {
                            "code": "invalid_payload",
                            "message": "payload is invalid",
                            "retryable": False,
                        },
                    },
                    {"index": 2, "status": "created", "task": task("t3", "e3"), "error": None},
                ]
            },
        )

    tasks = [
        TaskCreate(external_id="e1", payload={"text": "one"}),
        TaskCreate(external_id="e2", payload={"text": "two"}),
        TaskCreate(external_id="e3", payload={"text": "three"}),
    ]

    with client_for(handler) as client:
        results = client.tasks.batch_create("p1", tasks)

    assert [result.index for result in results] == [0, 1, 2]
    assert [result.status for result in results] == ["created", "error", "created"]
    assert results[1].task is None
    assert results[1].error is not None
    assert results[1].error.code == "invalid_payload"


def test_review_idempotent_same_verdict_and_conflict_on_different_verdict() -> None:
    applied: dict[str, str] = {}

def handler(request: httpx.Request) -> httpx.Response:
    assert request.method == "POST"
    assert api_path(request) == "/annotations/a1:review"
    payload = json.loads(request.content)
    verdict = payload["verdict"]
    existing = applied.get("a1")
    if existing is None:
        applied["a1"] = verdict
        return response(
            200,
            {
                "annotation_id": "a1",
                "verdict": verdict,
                "note": payload["note"],
                "already_applied": False,
            },
        )
    if existing == verdict:
        return response(
            200,
            {
                "annotation_id": "a1",
                "verdict": verdict,
                "note": payload["note"],
                "already_applied": True,
            },
        )
    return response(
        409,
        {"error": {"code": "conflicting_review", "message": "different verdict", "retryable": False}},
    )

with client_for(handler) as client:
    first = client.annotations.review("a1", verdict="approve", note="ok")
    second = client.annotations.review("a1", verdict="approve", note="ok")
    with pytest.raises(ConflictError) as exc_info:
        client.annotations.review("a1", verdict="reject", note="bad")

assert first.already_applied is False
assert second.already_applied is True
assert exc_info.value.error is not None
assert exc_info.value.error.code == "conflicting_review"

from __future__ import annotations

from .models import Error


class LumenAPIError(Exception):
    """Base exception for Lumen API errors."""

    def __init__(
        self,
        message: str,
        *,
        error: Error | None = None,
        status_code: int | None = None,
    ) -> None:
        super().__init__(message)
        self.error = error
        self.status_code = status_code


class NotFoundError(LumenAPIError):
    """Raised when a requested resource does not exist."""


class RateLimitError(LumenAPIError):
    """Raised when a rate limit response remains after retries are exhausted."""


class ConflictError(LumenAPIError):
    """Raised when a request conflicts with existing state."""


class StaleCursorError(LumenAPIError):
    """Raised when an API cursor has expired."""
